type Walk struct {
	path         string
	showIcons    bool
	dirOnly      bool
	hideHidden   bool
	preview      bool
	withBorder   bool
	fuzzy        bool
}

func main() {
	if len(os.Args) > 1 && os.Args[1] == "--help" {
		printHelp()
		os.Exit(0)
	}
	if len(os.Args) > 1 && os.Args[1] == "--version" {
		fmt.Println("v1.13.0")
		os.Exit(0)
	}

	w := &Walk{}
	showIcons := false
	dirOnly := false
	hideHidden := false
	preview := false
	withBorder := false
	fuzzy := false

	for i := 1; i < len(os.Args); i++ {
		switch os.Args[i] {
		case "--icons":
			showIcons = true
		case "--dir-only":
			dirOnly = true
		case "--hide-hidden":
			hideHidden = true
		case "--preview":
			preview = true
		case "--with-border":
			withBorder = true
		case "--fuzzy":
			fuzzy = true
		}
	}

	w.showIcons = showIcons
	w.dirOnly = dirOnly
	w.hideHidden = hideHidden
	w.preview = preview
	w.withBorder = withBorder
	w.fuzzy = fuzzy

	if len(os.Args) > 2 {
		w.path = os.Args[2]
	} else {
		w.path = "."
	}

	files := listFiles(w.path, w)
	printFiles(files, w)
}

func printHelp() {
	fmt.Println()
	fmt.Println("  walk v1.13.0")
	fmt.Println()
	fmt.Println("  Usage: walk [path]")
